import uuid

from dynamodb.entity.todo_list.todo_list_entity import TodoListEntity
from dynamodb.entity.todo_list.todo_list_entity_repo import (
    TodoListEntityRepo,
    TodoListQueryResponse,
)


class TodoListEntityService:

    def __init__(self, repo: TodoListEntityRepo):
        self.repo = repo

    def put_todo_list(self, todo_list: TodoListEntity) -> TodoListEntity:
        todo_list_dict = todo_list.to_dict()
        todo_list = TodoListEntity.from_dict(todo_list_dict)
        todo_list.pk = TodoListEntity.entity_type.value
        todo_list.sk = f"{TodoListEntity.entity_type.value}#{str(uuid.uuid4())}"
        self.repo.put_todo_list(todo_list=todo_list)
        return todo_list

    def find_all_todo_lists(self, next_token: str, limit: int) -> TodoListQueryResponse:
        return self.repo.find_all_todo_lists(next_token=next_token, limit=limit)
